            unsigned long start = 0;
            unsigned long size = 0;
            if (sscanf(line, "sym %127s 0x%lx 0x%lx", sym.name, &start, &size) == 3) {
                sym.start = start;
                sym.size = size;
                sf_sym_t *next =
                    realloc(map->syms, (size_t)(map->count + 1) * sizeof(sf_sym_t));
